2	 * @license
3	 * Copyright 2025 Google LLC
4	 * SPDX-License-Identifier: Apache-2.0
5	 */
6	
7	import React, {
8	  useState,
9	  useEffect,
10	  useRef,
11	  useLayoutEffect,
12	  useCallback,
13	  useMemo,
14	} from 'react';
15	import { Box, getInnerHeight, getScrollHeight, type DOMElement } from 'ink';
16	import { useKeypress, type Key } from '../../hooks/useKeypress.js';
17	import { useScrollable } from '../../contexts/ScrollProvider.js';
18	import { useAnimatedScrollbar } from '../../hooks/useAnimatedScrollbar.js';
19	import { useBatchedScroll } from '../../hooks/useBatchedScroll.js';
20	import { keyMatchers, Command } from '../../keyMatchers.js';
21	
22	interface ScrollableProps {
23	  children?: React.ReactNode;
24	  width?: number;
25	  height?: number | string;
26	  maxWidth?: number;
27	  maxHeight?: number;
28	  hasFocus: boolean;
29	  scrollToBottom?: boolean;
30	  flexGrow?: number;
31	}
32	
33	export const Scrollable: React.FC<ScrollableProps> = ({
34	  children,
35	  width,
36	  height,
37	  maxWidth,
38	  maxHeight,
39	  hasFocus,
40	  scrollToBottom,
41	  flexGrow,
42	}) => {
43	  const [scrollTop, setScrollTop] = useState(0);
44	  const ref = useRef<DOMElement>(null);
45	  const [size, setSize] = useState({
46	    innerHeight: 0,
47	    scrollHeight: 0,
48	  });
49	  const sizeRef = useRef(size);
50	  useEffect(() => {
51	    sizeRef.current = size;
52	  }, [size]);
53	
54	  const childrenCountRef = useRef(0);
55	
56	  // This effect needs to run on every render to correctly measure the container
57	  // and scroll to the bottom if new children are added. The if conditions
58	  // prevent infinite loops.
59	  // eslint-disable-next-line react-hooks/exhaustive-deps
60	  useLayoutEffect(() => {
61	    if (!ref.current) {
62	      return;
63	    }
64	    const innerHeight = Math.round(getInnerHeight(ref.current));
65	    const scrollHeight = Math.round(getScrollHeight(ref.current));
66	
67	    const isAtBottom = scrollTop >= size.scrollHeight - size.innerHeight - 1;
68	
69	    if (
70	      size.innerHeight !== innerHeight ||
71	      size.scrollHeight !== scrollHeight
72	    ) {
73	      setSize({ innerHeight, scrollHeight });
74	      if (isAtBottom) {
75	        setScrollTop(Math.max(0, scrollHeight - innerHeight));
76	      }
77	    }
78	
79	    const childCountCurrent = React.Children.count(children);
80	    if (scrollToBottom && childrenCountRef.current !== childCountCurrent) {
81	      setScrollTop(Math.max(0, scrollHeight - innerHeight));
82	    }
83	    childrenCountRef.current = childCountCurrent;
84	  });
85	
86	  const { getScrollTop, setPendingScrollTop } = useBatchedScroll(scrollTop);
87	
88	  const scrollBy = useCallback(
89	    (delta: number) => {
90	      const { scrollHeight, innerHeight } = sizeRef.current;
91	      const current = getScrollTop();
92	      const next = Math.min(
93	        Math.max(0, current + delta),
94	        Math.max(0, scrollHeight - innerHeight),
95	      );
96	      setPendingScrollTop(next);
97	      setScrollTop(next);
98	    },
99	    [sizeRef, getScrollTop, setPendingScrollTop],
100	  );
101	
102	  const { scrollbarColor, flashScrollbar, scrollByWithAnimation } =
103	    useAnimatedScrollbar(hasFocus, scrollBy);
104	
105	  useKeypress(
106	    (key: Key) => {
107	      const { scrollHeight, innerHeight } = sizeRef.current;
108	      const scrollTop = getScrollTop();
109	      const maxScroll = Math.max(0, scrollHeight - innerHeight);
110	
111	      // Only capture scroll-up events if there's room;
112	      // otherwise allow events to bubble.
113	      if (scrollTop > 0) {
114	        if (keyMatchers[Command.PAGE_UP](key)) {
115	          scrollByWithAnimation(-innerHeight);
116	          return true;
117	        }
118	        if (keyMatchers[Command.SCROLL_UP](key)) {
119	          scrollByWithAnimation(-1);
120	          return true;
121	        }
122	      }
123	
124	      // Only capture scroll-down events if there's room;
125	      // otherwise allow events to bubble.
126	      if (scrollTop < maxScroll) {
127	        if (keyMatchers[Command.PAGE_DOWN](key)) {
128	          scrollByWithAnimation(innerHeight);
129	          return true;
130	        }
131	        if (keyMatchers[Command.SCROLL_DOWN](key)) {
132	          scrollByWithAnimation(1);
133	          return true;
134	        }
135	      }
136	
137	      // bubble keypress
138	      return false;
139	    },
140	    { isActive: hasFocus },
141	  );
142	
143	  const getScrollState = useCallback(
144	    () => ({
145	      scrollTop: getScrollTop(),
146	      scrollHeight: size.scrollHeight,
147	      innerHeight: size.innerHeight,
148	    }),
149	    [getScrollTop, size.scrollHeight, size.innerHeight],
150	  );
151	
152	  const hasFocusCallback = useCallback(() => hasFocus, [hasFocus]);
153	
154	  const scrollableEntry = useMemo(
155	    () => ({
156	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
157	      ref: ref as React.RefObject<DOMElement>,
158	      getScrollState,
159	      scrollBy: scrollByWithAnimation,
160	      hasFocus: hasFocusCallback,
161	      flashScrollbar,
162	    }),
163	    [getScrollState, scrollByWithAnimation, hasFocusCallback, flashScrollbar],
164	  );
165	
166	  useScrollable(scrollableEntry, true);
167	
168	  return (
169	    <Box
170	      ref={ref}
171	      maxHeight={maxHeight}
172	      width={width ?? maxWidth}
173	      height={height}
174	      flexDirection="column"
175	      overflowY="scroll"
176	      overflowX="hidden"
177	      scrollTop={scrollTop}
178	      flexGrow={flexGrow}
179	      scrollbarThumbColor={scrollbarColor}
180	    >
181	      {/*
182	        This inner box is necessary to prevent the parent from shrinking
183	        based on the children's content. It also adds a right padding to
184	        make room for the scrollbar.
185	      */}
186	      <Box flexShrink={0} paddingRight={1} flexDirection="column">
187	        {children}
188	      </Box>
189	    </Box>
190	  );
